// Solution
class Student {
  String name;
  int id;
  String[] courses = new String[5];
  int[] grades = new int[5];
  int courseCount = 0;

  void enroll(String course) {
    courses[courseCount] = course;
    courseCount++;
  }

  void setGrade(String course, int grade) {
    for (int i = 0; i < courseCount; i++) {
      if (courses[i].equals(course)) {
        grades[i] = grade;
      }
    }
  }
}
